WITH filtered AS (SELECT *, SIZE(tags) AS tags_count FROM products WHERE supplier_id IS NOT NULL AND launch_date < '2024-04-01'), kept AS (SELECT s.* FROM filtered s WHERE NOT EXISTS (SELECT 1 FROM inventory x WHERE x.product_id = s.id AND x.product_id IN (3, 8, 10))), latest_match AS (SELECT s.id, s.product_name, s.category, s.cost, s.launch_date, s.tags, s.tags_count, top1.unit_price, top1.order_item_quantity FROM kept s LEFT JOIN LATERAL (SELECT c.unit_price, c.quantity AS order_item_quantity FROM order_items c WHERE c.product_id = s.id ORDER BY c.quantity DESC, c.id DESC LIMIT 1) top1 ON TRUE), cleaned AS (SELECT id, product_name, category, cost, launch_date, unit_price, order_item_quantity, LEAST(unit_price, order_item_quantity) AS least_unit_price_order_item_quantity, REGEXP_REPLACE(product_name, ' ', '_') AS product_name_slug FROM latest_match WHERE product_name NOT LIKE '%Coff%'), eligible AS (SELECT s.* FROM cleaned s WHERE EXISTS (SELECT 1 FROM store_sales ch WHERE ch.product_id = s.id AND ch.store_id IN (1, 4))), scored AS (SELECT id, product_name, cost, unit_price, least_unit_price_order_item_quantity, product_name_slug, LAG(order_item_quantity, 1) OVER (PARTITION BY category ORDER BY launch_date, id) AS prev_order_item_quantity, CUME_DIST() OVER (PARTITION BY category ORDER BY order_item_quantity DESC NULLS LAST) AS order_item_quantity_cume_dist, SUM(unit_price) OVER (PARTITION BY YEAR(launch_date), category ORDER BY unit_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_unit_price FROM eligible) SELECT CASE WHEN prev_order_item_quantity >= 8 THEN 'LARGE' ELSE 'SMALL' END AS prev_order_item_quantity_tier, CASE WHEN cost >= 540 THEN 'HIGH' ELSE 'LOW' END AS cost_tier, COUNT(*) AS row_count, AVG(order_item_quantity_cume_dist) AS avg_order_item_quantity_cume_dist, APPROX_PERCENTILE(running_unit_price, 0.95) AS running_unit_price_p95, APPROX_PERCENTILE(running_unit_price, 0.95) AS running_unit_price_p95_2 FROM scored GROUP BY GROUPING SETS ((CASE WHEN prev_order_item_quantity >= 8 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN cost >= 540 THEN 'HIGH' ELSE 'LOW' END), (CASE WHEN prev_order_item_quantity >= 8 THEN 'LARGE' ELSE 'SMALL' END))
